public interface NotificationSender {
    void send(
        String target,
        String message
    );
}

@Component
public class EmailNotificationSender
        implements NotificationSender {

    @Override
    public void send(
            String target,
            String message
    ) {
        System.out.println(
            "Sending email to " + target
        );
    }
}

@Component
public class SmsNotificationSender
        implements NotificationSender {

    @Override
    public void send(
            String target,
            String message
    ) {
        System.out.println(
            "Sending SMS to " + target
        );
    }
}

@Service
public class NotificationService {
    private final NotificationSender sender;

    public NotificationService(
        @Qualifier("smsNotificationSender")
        NotificationSender sender
    ) {
        this.sender = sender;
    }
}
